package com.example.dsatracker.dto;import jakarta.validation.constraints.Min;import jakarta.validation.constraints.NotNull;import lombok.*;@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builderpublic class SubmissionRequestDTO {    @NotNull    private Long problemId;    @NotNull    @Min(1)    private Integer attempts;    @NotNull    @Min(0)    private Double timeTaken;    @NotNull    @Min(0)    private Integer confidenceScore;    @NotNull    private Boolean solutionViewed;    @NotNull    @Min(0)    private Double timeAway;}